import{_ as a,o as i,c as t,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Designing Ceph Clusters Whats the Right Durability","description":"","frontmatter":{"title":"Designing Ceph Clusters Whats the Right Durability","date":"2026-06-26T00:00:00.000Z","updated":"2026-06-26T00:00:00.000Z","tags":["Ceph","分布式存储","Erasure Coding","性能优化","高可用性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Designing_Ceph_Clusters_What_s_the_Right_Durability.md","filePath":"posts/2026/Designing_Ceph_Clusters_What_s_the_Right_Durability.md","lastUpdated":null}'),l={name:"posts/2026/Designing_Ceph_Clusters_What_s_the_Right_Durability.md"};function o(s,e,n,h,p,d){return i(),t("div",null,[...e[0]||(e[0]=[r('<h2 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h2><p>本次演讲由 OSNexus 的工程师主讲，主题是 Ceph 集群设计中的持久性（durability）问题。演讲从 Ceph 基础架构入手，深入讲解了 placement group 的修复机制，并重点讨论了 Erasure Coding 布局的选择策略，包括多站点场景下的持久性设计。最后介绍了双层持久性架构和集群设计工具。</p><h2 id="ceph-基础架构回顾" tabindex="-1">Ceph 基础架构回顾 <a class="header-anchor" href="#ceph-基础架构回顾" aria-label="Permalink to &quot;Ceph 基础架构回顾&quot;">​</a></h2><p>Ceph 的数据组织分为三个层次：</p><ul><li><strong>Pool</strong>：Pool 是 Placement Group（PG）的集合，类似于 RAID stripe 的概念，用于将数据均匀分散到所有底层设备上。</li><li><strong>Placement Group（PG）</strong>：每个 PG 会分布在多个 OSD 上。例如 replica 3 模式下，一个 PG 会在 3 个不同 host 上各存一份副本。Pool 中的所有 PG 类型一致，replica 3 的 pool 中所有 PG 都是 3 副本。</li><li><strong>OSD</strong>：底层存储介质，是共享资源。多个 pool 的 PG 会共享同一组 OSD。</li></ul><p>一个完整的存储系统（如 CephFS 或对象存储）由多个 pool 组成。例如 CephFS 有一个或多个 data pool 加一个 metadata pool，对象存储则有 bucket index pool 和 bucket data pool。</p><h2 id="pg-数量计算" tabindex="-1">PG 数量计算 <a class="header-anchor" href="#pg-数量计算" aria-label="Permalink to &quot;PG 数量计算&quot;">​</a></h2><p>PG 数量基于集群 OSD 数量计算。以 24 个 OSD 的小集群为例，按公式计算大约每个 OSD 分配 64 个 PG。实际演示中为了可读性只展示了 4 个 PG。</p><h2 id="故障修复机制" tabindex="-1">故障修复机制 <a class="header-anchor" href="#故障修复机制" aria-label="Permalink to &quot;故障修复机制&quot;">​</a></h2><h3 id="单盘故障流程" tabindex="-1">单盘故障流程 <a class="header-anchor" href="#单盘故障流程" aria-label="Permalink to &quot;单盘故障流程&quot;">​</a></h3><ol><li><strong>检测阶段</strong>：Monitor 检测到 OSD 无法通信，将对应 PG 标记为 down 状态，进入 peering 状态。</li><li><strong>短暂 IO 暂停</strong>：peering 过程持续数秒，期间 IO 短暂暂停。对大多数工作负载影响不大，但对媒体/电信等延迟敏感场景可能是个问题。</li><li><strong>降级运行</strong>：peering 完成后，PG 进入 active degraded 状态，仍可接受 IO（replica 3 仍有 2 份可用）。</li><li><strong>踢出 OSD</strong>：如果故障盘未恢复，OSD 从 down 转为 out 状态，被踢出集群。</li><li><strong>重建过程</strong>：集群开始 backfill 过程，将受影响的 PG 重新映射到其他健康 OSD 上。</li><li><strong>恢复完成</strong>：集群回到 100% 健康状态。</li></ol><p>Ceph 的设计精髓在于无需热备盘即可自愈——故障盘被替换后重新加入集群即可。</p><h3 id="多盘故障与-min-size" tabindex="-1">多盘故障与 min size <a class="header-anchor" href="#多盘故障与-min-size" aria-label="Permalink to &quot;多盘故障与 min size&quot;">​</a></h3><p>如果同一 PG 的 2 个 OSD 在短时间内相继故障（在重建完成前），集群会停止对该 PG 的写入，因为此时等同于 RAID 0，无任何保护。</p><p><strong>min size 设置</strong>：</p><ul><li>replica 3 建议 min size 设为 2，确保始终有足够副本进行数据校正（如 bit rot 修复）。</li><li>min size 始终设为 2 即可，即使副本数设为 4 或 5，因为 2 是能自我修复的最小数量。</li><li>原理同样适用于 Erasure Coding。</li></ul><h3 id="ceph-的分布式重建优势" tabindex="-1">Ceph 的分布式重建优势 <a class="header-anchor" href="#ceph-的分布式重建优势" aria-label="Permalink to &quot;Ceph 的分布式重建优势&quot;">​</a></h3><p>与传统 RAID 不同，Ceph 的重建是集群级协作的。当一个 OSD 故障时，所有参与该 OSD 上 PG 的其他 OSD 都会参与数据重建，多个 OSD 并行工作。而传统 RAID 只能依赖同一 stripe set 中剩余的几块盘加上热备盘。Ceph 的重建速度可比传统 RAID 快 10 倍。</p><h2 id="erasure-coding-布局选择" tabindex="-1">Erasure Coding 布局选择 <a class="header-anchor" href="#erasure-coding-布局选择" aria-label="Permalink to &quot;Erasure Coding 布局选择&quot;">​</a></h2><h3 id="基本公式" tabindex="-1">基本公式 <a class="header-anchor" href="#基本公式" aria-label="Permalink to &quot;基本公式&quot;">​</a></h3><p>Erasure Coding 中 K 为数据块数，M 为校验块数。最小可用块数要求为 <strong>K + 1</strong>（所有数据块 + 至少 1 个校验块），类似于 replica 3 至少需要 2 份副本。</p><h3 id="单站点场景" tabindex="-1">单站点场景 <a class="header-anchor" href="#单站点场景" aria-label="Permalink to &quot;单站点场景&quot;">​</a></h3><p>4+2 布局在单机架内是安全的——丢失 1 个 host（假设最多丢 2 个块），仍有 4 个数据块 + 1 个校验块，满足 K+1 要求。</p><p><strong>关键参数</strong>：<code>ceph mon OSD subtree limit</code> 默认值为 rack，如果需要维护一个节点（固件升级等），建议改为 host，避免集群在节点下线时触发大规模数据迁移。对于 24TB 大容量盘的集群，迁移一个节点的数据可能耗时一个月以上。</p><h3 id="多站点场景的问题" tabindex="-1">多站点场景的问题 <a class="header-anchor" href="#多站点场景的问题" aria-label="Permalink to &quot;多站点场景的问题&quot;">​</a></h3><p>将 4+2 布局应用于两个站点时，如果每个站点放 3 个块（2 个数据块 + 1 个校验块，或反之），单个站点故障可能导致所有校验块丢失（K+0），集群停止写入。</p><p><strong>修复方案 1：增加校验块</strong> 将布局从 4+2 改为 3+3，每个站点各放 2 个数据块 + 1 个校验块。单站点故障后仍有 1 个校验块，满足 K+1 要求。</p><p><strong>更严格的场景：站点故障 + 单盘故障</strong> 如果站点故障的同时另一站点还有一块盘故障，3+3 也会变为 K+0。此时需要改为 2+4 布局，但效率仅 33%。</p><p><strong>优化技巧：翻倍 stripe 长度</strong> 将 3+3 扩展为 6+6，仍然 50% 效率，但多出 1 个校验块，可承受站点故障 + 额外 1 盘故障。每个 host 放 2 个块，站点故障后仍有 1 个校验块剩余。</p><h2 id="双层持久性架构-double-layered-durability" tabindex="-1">双层持久性架构（Double-Layered Durability） <a class="header-anchor" href="#双层持久性架构-double-layered-durability" aria-label="Permalink to &quot;双层持久性架构（Double-Layered Durability）&quot;">​</a></h2><h3 id="核心思路" tabindex="-1">核心思路 <a class="header-anchor" href="#核心思路" aria-label="Permalink to &quot;核心思路&quot;">​</a></h3><p>在 OSD 下层使用 SAN 或其他 RAID 技术（如 Seagate Exos Protect、Zynor 的 NVMe RAID 方案），虚拟设备背后由 RAID 保护。这与公有云提供商的策略一致——AWS 据称使用了三层持久性保护。</p><h3 id="优势" tabindex="-1">优势 <a class="header-anchor" href="#优势" aria-label="Permalink to &quot;优势&quot;">​</a></h3><ul><li><strong>无感知修复</strong>：底层盘故障时，RAID 层自行重建，Ceph 集群完全无感知——无 peering、无暂停、无降级。</li><li><strong>极端容错</strong>：即使每个节点同时各坏一块盘，Ceph 集群也无影响。</li><li><strong>持久性大幅提升</strong>：从 9-11 个 9 跃升至 14-20 个 9 的持久性。</li><li><strong>消除跨站点带宽压力</strong>：多站点场景下，盘故障修复不再需要跨 WAN 拉取数据重建，全部在本地 RAID 层完成。</li><li><strong>运维简化</strong>：大集群（3000 盘、2% 年故障率 = 60 块/年）不再长期处于 rebuild 状态，Ceph 集群始终健康，scrub 等操作不受影响。</li></ul><h3 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h3><ul><li>10PB+ 大规模集群</li><li>多站点部署且需要消除跨站点重建带宽开销</li></ul><h2 id="集群设计工具" tabindex="-1">集群设计工具 <a class="header-anchor" href="#集群设计工具" aria-label="Permalink to &quot;集群设计工具&quot;">​</a></h2><p>OSNexus 提供了 Ceph 集群设计工具（osnexus.com/cephdesigner），支持：</p><ul><li>选择硬件厂商和型号（主流 JBOD、服务器）</li><li>输入目标容量，自动计算 BOM</li><li>估算性能、功耗</li><li>自动调整 CPU、网络等配置</li><li>metadata OSD 大小检查（对对象存储和文件存储至关重要）</li><li>计划加入持久性分析（Markov chain、MTTDL 指数）</li></ul><h2 id="关键决策与后续行动" tabindex="-1">关键决策与后续行动 <a class="header-anchor" href="#关键决策与后续行动" aria-label="Permalink to &quot;关键决策与后续行动&quot;">​</a></h2><ul><li>单站点部署推荐 4+2 或 6+3（后者更安全）</li><li>多站点部署必须根据 failure domain 调整 EC 布局，确保站点故障后仍有校验块</li><li>大规模集群或多站点场景建议考虑双层持久性架构</li><li>维护节点时务必将 subtree limit 从 rack 改为 host</li><li>后续将加入持久性 nines 分析功能到设计工具中</li></ul>',41)])])}const c=a(l,[["render",o]]);export{g as __pageData,c as default};
